import{_ as t,o as a,c as r,a6 as d}from"./chunks/framework.DIp0zHSV.js";const m=JSON.parse('{"title":"Developer Guide","description":"","frontmatter":{},"headers":[],"relativePath":"development/index.md","filePath":"development/index.md","lastUpdated":1794278866000}'),s={name:"development/index.md"};function o(i,e,n,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="developer-guide" tabindex="-1">Developer Guide <a class="header-anchor" href="#developer-guide" aria-label="Permalink to &quot;Developer Guide&quot;">​</a></h1><p>Documentation for developers working on LCARdS itself: adding cards, options, editors, packs and core services, and the APIs they use. Everything lives in one repository and ships as one bundle, so these guides are about changing that code; there is no plugin API for cards or packs shipped separately. How the pieces work inside is in the <a href="./../architecture/">Architecture</a> section.</p><h2 id="how-to-guides" tabindex="-1">How-to Guides <a class="header-anchor" href="#how-to-guides" aria-label="Permalink to &quot;How-to Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Description</th></tr></thead><tbody><tr><td><a href="./custom-card.html">Building a Custom Card</a></td><td>Extend <code>LCARdSCard</code>, the schema, registration in <code>src/lcards-main.js</code>, element types, card size, build and test</td></tr><tr><td><a href="./adding-a-card-option.html">Adding a Card Option</a></td><td>A new or changed YAML key end to end: schema, runtime, editor, docs, registries and tests</td></tr><tr><td><a href="./building-an-editor.html">Building a Studio Editor</a></td><td>Studio dialogs (the dialog pattern, live preview, the shared panels and controls, launching from the card editor), plus a basic <code>LCARdSBaseEditor</code> card editor</td></tr><tr><td><a href="./building-a-pack.html">Building a Pack</a></td><td>Style presets, components, themes, rules, assets and sound schemes in a built-in pack</td></tr><tr><td><a href="./adding-a-core-service.html">Adding a Core Service</a></td><td>A <code>BaseService</code> singleton: startup order, HASS distribution, debug info, tests and docs</td></tr><tr><td><a href="./testing.html">Testing</a></td><td>The test layers (node, browser, visual, real Home Assistant, docs site), their helpers and when to use each</td></tr><tr><td><a href="./typescript.html">Type Checking</a></td><td>How TypeScript checks our JavaScript, the rules for new code, and how to fix common errors</td></tr><tr><td><a href="./colour-resolution.html">Colour Resolution</a></td><td>Resolving colours, theme tokens and computed expressions (<code>darken</code>, <code>lighten</code>, <code>alpha</code>, ...) in CSS, SVG, Canvas2D and anime.js</td></tr></tbody></table><h2 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Description</th></tr></thead><tbody><tr><td><a href="./anim-api.html">Animation API</a></td><td><code>window.lcards.anim.*</code>: anime.js v4 access, helpers, presets, scopes</td></tr><tr><td><a href="./assets-api.html">Assets and SVG API</a></td><td>Font loading, SVG cache, SVG and anchor helpers, text measure cache</td></tr><tr><td><a href="./backend-api.html">Backend WS API</a></td><td><code>lcards/*</code> WebSocket commands and the integration&#39;s actions: storage, Home Assistant service targeting, degraded mode</td></tr><tr><td><a href="./debug-api.html">Debug API</a></td><td>Console introspection: log level, core singletons, MSD cards, data sources</td></tr><tr><td><a href="./helpers-api.html">Helpers API</a></td><td>LCARdS&#39;s own helper registry: the <code>input_*</code> helpers it creates, reads, writes and watches</td></tr></tbody></table><h2 id="css-and-theming" tabindex="-1">CSS and Theming <a class="header-anchor" href="#css-and-theming" aria-label="Permalink to &quot;CSS and Theming&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Description</th></tr></thead><tbody><tr><td><a href="./ha-css-vars.html">Home Assistant CSS Variables</a></td><td>The Home Assistant CSS variables LCARdS uses (minimum Home Assistant 2026.11), their default values and where LCARdS uses them</td></tr></tbody></table><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../architecture/">Architecture overview</a></td><td>How the bundle, the integration, the core and the cards fit together</td></tr><tr><td><a href="./../architecture/cards/lcards-card-foundation.html">Card Foundation</a></td><td><code>LCARdSNativeCard</code> and <code>LCARdSCard</code>: lifecycle, HASS flow, entities, rules, preview mode, cleanup</td></tr><tr><td><a href="./../architecture/subsystems/">Core Subsystems</a></td><td>Every <code>window.lcards.core.*</code> service, the startup order and how HASS reaches them</td></tr></tbody></table><h2 id="build-test-and-release" tabindex="-1">Build, test and release <a class="header-anchor" href="#build-test-and-release" aria-label="Permalink to &quot;Build, test and release&quot;">​</a></h2><p>The commands are kept in one place, <code>COOKBOOK.md</code> in the repository root (not on this site): its sections are <a href="https://github.com/snootched/lcards/blob/main/COOKBOOK.md#daily-loop" target="_blank" rel="noreferrer">Daily loop</a> (build, hard refresh, tests, docs server), <a href="https://github.com/snootched/lcards/blob/main/COOKBOOK.md#npm-scripts" target="_blank" rel="noreferrer">npm scripts</a> (every script, and which ones <code>npm run build</code> already runs), <a href="https://github.com/snootched/lcards/blob/main/COOKBOOK.md#tests" target="_blank" rel="noreferrer">Tests</a>, <a href="https://github.com/snootched/lcards/blob/main/COOKBOOK.md#ci-workflows" target="_blank" rel="noreferrer">CI workflows</a>, <a href="https://github.com/snootched/lcards/blob/main/COOKBOOK.md#docs-site" target="_blank" rel="noreferrer">Docs site</a> and <a href="https://github.com/snootched/lcards/blob/main/COOKBOOK.md#releases" target="_blank" rel="noreferrer">Releases</a>. <code>npm run help</code> prints the same script list in the terminal.</p><p>The short version:</p><ul><li><code>npm run build</code> is the only build, for development and releases alike. It runs every validator first (strict doc examples, schema descriptions, em dashes and &quot;Home Assistant&quot; in the docs, CSS variables, the Home Assistant compatibility lint, typecheck) and writes the bundle into <code>custom_components/lcards/</code>. Hard-refresh the browser afterwards (Ctrl+Shift+R).</li><li><code>npm test</code> runs the node tests; <code>npm run test:browser</code> the browser tests against the built bundle. CI runs both, plus the checks inside the build.</li><li><code>npm run validate:config -- &lt;file&gt;</code> checks any LCARdS YAML (a card, a view, a dashboard) with the same checker as the doc examples.</li><li>Code rules live in <code>CLAUDE.md</code> and <code>.github/instructions/*.md</code>; read the file for the area you change.</li></ul>',14)])])}const p=t(s,[["render",o]]);export{m as __pageData,p as default};
